import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.BNNhFWPR.js";const g=JSON.parse('{"title":"Exporting a game","description":"Turn a project into a standalone executable, and check that it contains everything it needs.","frontmatter":{"id":"exporting","title":"Exporting a game","order":14,"description":"Turn a project into a standalone executable, and check that it contains everything it needs.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/manual/exporting.md"},"headers":[],"relativePath":"manual/exporting.md","filePath":"en/manual/exporting.md"}'),o={name:"manual/exporting.md"};function n(r,e,d,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="exporting-a-game" tabindex="-1">Exporting a game <a class="header-anchor" href="#exporting-a-game" aria-label="Permalink to &quot;Exporting a game&quot;">​</a></h1><p>An exported game is a single executable: a copy of <code>atmo-export</code>, the engine without the editor, followed by the files of the project. Players need neither the engine nor the project.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export {#export}&quot;">​</a></h2><ol><li><p>Build the export runtime, in the folder of the engine:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atmo-export</span></span></code></pre></div></li><li><p>Set <code>default_scene</code> in the <a href="/latest/manual/project-settings#app" class="atmo-ref atmo-ref--page" data-preview="Every project setting, its default value and what it changes.">project settings</a>: the game starts with it.</p></li><li><p>Export the project, with the editor binary:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my-game</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/atmo-export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my-game-executable</span></span></code></pre></div></li></ol><p>There is no export button in the editor. On Windows, give the executable a name that ends in <code>.exe</code>.</p><p>The game runs on the system <code>atmo-export</code> was built for. To export for another system, use an <code>atmo-export</code> built there.</p><h2 id="packed" tabindex="-1">What is packed <a class="header-anchor" href="#packed" aria-label="Permalink to &quot;What is packed {#packed}&quot;">​</a></h2><p>Every file of the project folder is packed, including the scripts, the project settings and files that the game does not use. Keep anything private out of the project folder.</p><p><a href="/latest/manual/shaders-and-materials#editing-and-exporting" class="atmo-ref atmo-ref--page" data-preview="Write Slang shaders for sprites and post-processing, and set their parameters with materials.">Material shaders</a> are compiled during the export, and their errors are logged.</p><p>To list the files of an exported game, or print one of them:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --read</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my-game-executable</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --read</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my-game-executable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.ascn</span></span></code></pre></div><h2 id="checklist" tabindex="-1">Before exporting <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Before exporting {#checklist}&quot;">​</a></h2><ul><li><p>Use <a href="/latest/getting-started/projects#project-paths" class="atmo-ref atmo-ref--page" data-preview="Where projects are stored on your computer and how to reach their files with project:// paths.">`project://` paths</a> everywhere. Other paths only work on your computer.</p></li><li><p>Copy the engine files that the game uses into the project, at the same place. The engine&#39;s files are found in the editor but <strong>not in exported games</strong>:</p><table tabindex="0"><thead><tr><th>File</th><th>Used by</th></tr></thead><tbody><tr><td><code>assets/fonts/Nunito/Nunito.ttf</code></td><td>Labels and text fields, unless their font is changed</td></tr><tr><td><code>assets/atmo.png</code></td><td>Nothing, unless the game shows it. New projects have it.</td></tr></tbody></table><p>They are in the <code>assets</code> folder of the engine&#39;s source code. Copy the license of the fonts too.</p></li><li><p>Check the upper and lower case of the paths, which matters on every system once exported.</p></li><li><p>Run the exported game once from a terminal, and read its log for <code>File not found in packed file system</code>.</p></li></ul><h2 id="differences" tabindex="-1">Differences with run mode <a class="header-anchor" href="#differences" aria-label="Permalink to &quot;Differences with run mode {#differences}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In run mode</th><th>In an exported game</th></tr></thead><tbody><tr><td><a href="/latest/manual/project-settings#late" class="atmo-ref atmo-ref--page" data-preview="Every project setting, its default value and what it changes.">Late settings</a> are ignored</td><td>Every setting is read before the game starts</td></tr><tr><td>The project is read from the disk</td><td>The files are inside the executable, and read-only</td></tr><tr><td><code>user://</code> is the folder of the engine</td><td><code>user://</code> is a <a href="/latest/getting-started/projects#user-paths" class="atmo-ref atmo-ref--page" data-preview="Where projects are stored on your computer and how to reach their files with project:// paths.">folder of the game</a></td></tr><tr><td>The <a href="/latest/manual/mcp-server" class="atmo-ref atmo-ref--page" data-preview="Let an AI agent drive the editor or a running game through the Model Context Protocol.">MCP server</a> can be used</td><td>There is no MCP server</td></tr><tr><td>Addons are loaded</td><td>Addons are <a href="#known-issues">not loaded</a></td></tr></tbody></table><p>Check in the exported game that the window size and the physics behave as expected, since they can differ from what the Play button shows.</p><h2 id="options" tabindex="-1">Command-line options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Command-line options {#options}&quot;">​</a></h2><p>Exported games accept <code>--headless</code>, <code>--rendering-platform</code>, <code>--render-thread</code>, <code>--gpu-validation</code> and <code>--lang</code>: see <a href="/latest/getting-started/building-from-source#command-line" class="atmo-ref atmo-ref--page" data-preview="Install the toolchain and build the engine, its tests and the export runtime.">Command-line options</a>.</p><h2 id="known-issues" tabindex="-1">Known issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known issues {#known-issues}&quot;">​</a></h2><ul><li>Addons are not loaded: the log says <code>addon.json not found in addon directory</code>, even though the file is packed. Their assets can still be used by their path.</li><li>The default font is missing unless the project contains it.</li><li><code>Locale &#39;en-US&#39; not available</code> is logged when the game starts, and has no effect on games.</li></ul>',20)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
